<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchByTracking">Track</button>
        </div>
    </div>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (searchPerformed && trackedShipment is null)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}
else if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>@trackedShipment.TrackingNumber</strong> — @trackedShipment.Description
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Status</dt>
                <dd class="col-sm-9"><span class="badge @GetStatusBadgeClass(trackedShipment.Status)">@trackedShipment.Status</span></dd>

                <dt class="col-sm-3">Origin</dt>
                <dd class="col-sm-9">@trackedShipment.Origin</dd>

                <dt class="col-sm-3">Destination</dt>
                <dd class="col-sm-9">@trackedShipment.Destination</dd>

                <dt class="col-sm-3">Shipped Date</dt>
                <dd class="col-sm-9">@trackedShipment.ShippedDate.ToString("yyyy-MM-dd")</dd>

                <dt class="col-sm-3">Estimated Delivery</dt>
                <dd class="col-sm-9">@trackedShipment.EstimatedDelivery.ToString("yyyy-MM-dd")</dd>
            </dl>
        </div>
    </div>
}

<h2 class="mt-4">My Shipments</h2>

@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments on record.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
