using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "customer@example.com", Description = "Electronics - Laptop" },
        new() { Id = 2, TrackingNumber = "TRK-001235", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "customer@example.com", Description = "Auto Parts" },
        new() { Id = 3, TrackingNumber = "TRK-001236", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(10), CustomerEmail = "buyer@example.com", Description = "Medical Supplies" },
        new() { Id = 4, TrackingNumber = "TRK-001237", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "buyer@example.com", Description = "Textiles" },
        new() { Id = 5, TrackingNumber = "TRK-001238", Origin = "São Paulo, BR", Destination = "Toronto, CA", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "customer@example.com", Description = "Food Products" },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string customerEmail)
    {
        var result = _shipments
            .Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase))
            .ToList();
        return Task.FromResult(result);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
        {
            return Results.Ok(await service.GetAllShipmentsAsync());
        }).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
        {
            return Results.Ok(await service.GetShipmentsForCustomerAsync(email));
        });

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            await service.UpdateShipmentStatusAsync(id, status);
            return Results.NoContent();
        }).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));
    }
}

